<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.dusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Core','UI','Assets','Other'],colors=['#6366f1','#0d9488','#c2410c','#a855f7'],radius=68,circumference=2*Math.PI*radius
const values=computed(()=>dataset.value==='A'?[40,30,20,10]:dataset.value==='B'?[10,20,30,140]:dataset.value==='single'?[0,100,0,0]:[0,0,0,0])
const total=computed(()=>values.value.reduce((a,b)=>a+b,0))
const parts=computed(()=>values.value.map((value,i)=>({value,share:total.value?value/total.value:0,start:total.value?values.value.slice(0,i).reduce((a,b)=>a+b,0)/total.value:0})))
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="dusage-demo" aria-label="Local donut chart example"><p>Synthetic counts in four exclusive categories. The denominator is the sum of all four, including unselected categories. Selecting a category never filters or renormalizes the whole.</p><div class="dusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="single">One nonzero</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="dusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 320 215" role="img" aria-label="Clockwise parts of one total, starting at top. Exact counts and percentages are below."><circle class="dusage-track" cx="160" cy="96" :r="radius"/><template v-for="(part,i) in parts" :key="i"><circle v-if="part.value>0" class="dusage-segment" :class="{selected:selected===i}" cx="160" cy="96" :r="radius" :stroke="colors[i]" :stroke-dasharray="`${circumference*part.share} ${circumference*(1-part.share)}`" :stroke-dashoffset="-circumference*part.start" transform="rotate(-90 160 96)" :data-index="i"/></template><text x="160" y="91" text-anchor="middle" class="dusage-total">{{ total }}</text><text x="160" y="111" text-anchor="middle">total count</text><text x="160" y="195" text-anchor="middle">{{ total?'Top start · clockwise · one shared denominator':'No positive total: no slices or percentages' }}</text></svg><div role="group" aria-label="Select category" class="dusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i"><span :style="{background:colors[i]}" aria-hidden="true"></span>{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }} of {{ total }}; {{ total?(parts[selected].share*100).toFixed(1)+'%':'share undefined at total zero' }}. Selection does not change the denominator.</p><table class="dusage-data"><caption>Exact counts and shares, dataset {{ dataset }}</caption><thead><tr><th scope="col">Category</th><th scope="col">Count</th><th scope="col">Share</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ values[i] }}</td><td>{{ total?(parts[i].share*100).toFixed(1)+'%':'Not defined' }}</td></tr></tbody><tfoot><tr><th scope="row">Total</th><td>{{ total }}</td><td>{{ total?'100.0%':'Not defined' }}</td></tr></tfoot></table></template><p v-else role="status" class="dusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Counts and shares are withheld.':'No records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.dusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.dusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.dusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.dusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.dusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.dusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.dusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.dusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.dusage-demo .dusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.dusage-track{fill:none;stroke:var(--vp-c-divider);stroke-width:22}.dusage-segment{fill:none;stroke-width:22;stroke-linecap:butt;opacity:.7}.dusage-segment.selected{opacity:1;stroke-width:26}.dusage-choices{display:flex;gap:6px;flex-wrap:wrap}.dusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.dusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.dusage-data{display:table!important;width:100%;font-size:12px}.dusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.dusage-data :is(td,th){padding:6px!important}.dusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
